/* Minimal stand-in for Bootstrap's JS (written for the offline capture). The
 * router UI only uses bootstrap.Modal; modals just toggle a CSS class here. */
(function () {
  const instances = new WeakMap();
  class Modal {
    constructor(el) { this._el = el; instances.set(el, this); }
    static getInstance(el) { return instances.get(el) || null; }
    static getOrCreateInstance(el) { return instances.get(el) || new Modal(el); }
    show() { if (this._el) this._el.classList.add("show"); }
    hide() { if (this._el) this._el.classList.remove("show"); }
    toggle() { if (this._el) this._el.classList.toggle("show"); }
    dispose() {}
  }
  window.bootstrap = { Modal };
})();
